import{AuthService}from"./auth.service.js";export class PostsService{static API_URL="/api/posts";static async handleResponse(t,e){const o=t.headers.get("content-type");let s;if(!o||!o.includes("application/json")){const e=await t.text();throw new Error(e||"Too many requests, please try again later.")}if(s=await t.json(),!t.ok)throw new Error(s.message||e);return s}static async getAllPosts(){const t=AuthService.getToken(),e={};t&&(e.Authorization=`Bearer ${t}`);const o=await fetch(`${this.API_URL}/`,{headers:e});return this.handleResponse(o,"Failed to fetch posts")}static async getPostById(t){const e=AuthService.getToken(),o={};e&&(o.Authorization=`Bearer ${e}`);const s=await fetch(`${this.API_URL}/${t}`,{headers:o});return this.handleResponse(s,"Failed to fetch post")}static async getUserPosts(t){const e=AuthService.getToken(),o={};e&&(o.Authorization=`Bearer ${e}`);const s=await fetch(`${this.API_URL}/user/${t}`,{headers:o});return this.handleResponse(s,"Failed to fetch user posts")}static async createPost(t,e=null){const o=AuthService.getToken();if(!o)throw new Error("Not authenticated");const s=new FormData;s.append("content",t),e&&s.append("media",e);const n=await fetch(`${this.API_URL}/`,{method:"POST",headers:{Authorization:`Bearer ${o}`},body:s});return this.handleResponse(n,"Failed to create post")}static async updatePost(t,e){const o=AuthService.getToken();if(!o)throw new Error("Not authenticated");const s=await fetch(`${this.API_URL}/${t}`,{method:"PUT",headers:{"Content-Type":"application/json",Authorization:`Bearer ${o}`},body:JSON.stringify({content:e})});return this.handleResponse(s,"Failed to update post")}static async deletePost(t){const e=AuthService.getToken();if(!e)throw new Error("Not authenticated");const o=await fetch(`${this.API_URL}/${t}`,{method:"DELETE",headers:{Authorization:`Bearer ${e}`}});return this.handleResponse(o,"Failed to delete post")}static async upvotePost(t){const e=AuthService.getToken();if(!e)throw new Error("Not authenticated");const o=await fetch(`${this.API_URL}/${t}/upvote`,{method:"POST",headers:{Authorization:`Bearer ${e}`}});return this.handleResponse(o,"Failed to upvote post")}static async downvotePost(t){const e=AuthService.getToken();if(!e)throw new Error("Not authenticated");const o=await fetch(`${this.API_URL}/${t}/downvote`,{method:"POST",headers:{Authorization:`Bearer ${e}`}});return this.handleResponse(o,"Failed to downvote post")}static async getComments(t){const e=AuthService.getToken(),o={};e&&(o.Authorization=`Bearer ${e}`);const s=await fetch(`${this.API_URL}/${t}/comments`,{headers:o});return this.handleResponse(s,"Failed to fetch comments")}static async addComment(t,e){const o=AuthService.getToken();if(!o)throw new Error("Not authenticated");const s=await fetch(`${this.API_URL}/${t}/comments`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${o}`},body:JSON.stringify({content:e})});return this.handleResponse(s,"Failed to add comment")}static async deleteComment(t){const e=AuthService.getToken();if(!e)throw new Error("Not authenticated");const o=await fetch(`${this.API_URL}/comments/${t}`,{method:"DELETE",headers:{Authorization:`Bearer ${e}`}});return this.handleResponse(o,"Failed to delete comment")}}